// The one place the app gets its Supabase client from. In demo mode it is an in-memory stand-in
// (src/lib/demo/fakeSupabase.ts) so no data ever leaves the browser. Import from here, never from
// "@/integrations/supabase/client" directly (that file is regenerated by Lovable; ESLint enforces it).
import { supabase as realSupabase } from "@/integrations/supabase/client";
import { isDemo } from "@/lib/demo/demoMode";
import { createFakeSupabase } from "@/lib/demo/fakeSupabase";

export const supabase: typeof realSupabase = isDemo()
  ? (createFakeSupabase() as unknown as typeof realSupabase)
  : realSupabase;
